const tabId = 886078847;
const captions = await browserjs(tabId, async () => {
  const playerResponse = window.ytInitialPlayerResponse;
  const captionTracks = playerResponse?.captions?.playerCaptionsTracklistRenderer?.captionTracks;
  if (!captionTracks || captionTracks.length === 0) return null;
  const trackUrl = captionTracks[0].baseUrl;
  const resp = await fetch(trackUrl);
  const text = await resp.text();
  return text;
});

if (captions) {
  console.log("Caption track found! Length:", captions.length);
  // Parse simple text from XML
  const cleanText = captions.replace(/<[^>]+>/g, ' ').replace(/&#39;/g, "'").replace(/&quot;/g, '"').replace(/\s+/g, ' ');
  console.log("Sample transcript:", cleanText.slice(0, 2000));
} else {
  console.log("No caption track in ytInitialPlayerResponse");
}

