async function googleSearch(query) {
  await tool.navigate({ tabId, url: `https://www.google.com/search?q=${encodeURIComponent(query)}` });
  await tool.wait_for({ tabId, condition: "selector_visible", value: "#search, #rso", timeout_ms: 10000 });
  return await browserjs(tabId, () => {
    const results = Array.from(document.querySelectorAll("#rso .g, #rso div[data-hveid]")).map(el => {
      const a = el.querySelector("a");
      const title = el.querySelector("h3")?.innerText;
      const snippet = el.querySelector(".VwiC3b, [style*='-webkit-line-clamp']")?.innerText;
      return { title, url: a?.href, snippet };
    }).filter(r => r.title && r.url);
    return results.slice(0, 5);
  });
}

