const tabId = 886078866;

const modelsToSearch = [
  // Budget
  "Roborock Q10 S5+",
  "eufy C20 robot vacuum",
  "Lefant M5 Max robot vacuum",
  // Mid-Range
  "MOVA V50 Ultra Complete robot vacuum",
  "Dreame D30 Ultra robot vacuum",
  "Ecovacs Deebot T90 Pro Omni robot vacuum",
  // Premium
  "Roborock Qrevo Curv 2 Flow robot vacuum",
  "Dreame X60 Max Ultra Complete robot vacuum",
  "Narwal Flow 2 robot vacuum"
];

const candidateLinks = {};

for (const model of modelsToSearch) {
  await tool.navigate({ tabId, url: `https://duckduckgo.com/?q=${encodeURIComponent(model)}` });
  await tool.wait_for({ tabId, condition: "selector_visible", value: "[data-testid='result']", timeout_ms: 8000 });

  const results = await browserjs(tabId, () => {
    const items = Array.from(document.querySelectorAll('[data-testid="result"]')).map(el => {
      const a = el.querySelector('a[data-testid="result-title-a"]');
      const snippet = el.querySelector('[data-result="snippet"]')?.innerText;
      return { title: a?.innerText, url: a?.href, snippet };
    });
    return items.slice(0, 6);
  });
  candidateLinks[model] = results;
  console.log(`=== ${model} ===`);
  for (const r of results.slice(0, 3)) {
    console.log(`- ${r.title} | ${r.url}`);
  }
}

